-- Phase 2 execution: the provider guard's pause reason (plan 7.3, UI_FLOWS 19
-- #5), the development host login's reachability on the workers row (UI_FLOWS
-- 19 #7), and one trigger change so recovery can close the event stream of an
-- attempt whose lease it revoked.
--
-- Generated by drizzle-kit, then edited: the trigger part at the end is
-- hand-written (Drizzle does not model triggers). The new `network` platform
-- event subtype (UI_FLOWS 19 #6) needs no DDL: subtypes live in the payload
-- and no CHECK reads them.

-- Experiments: PAUSE_REASONS gains provider_disconnected. A CHECK change
-- fires no row trigger, and existing rows hold only the older values.
ALTER TABLE "experiments" DROP CONSTRAINT "experiments_pause_reason_ck";--> statement-breakpoint

-- Workers: NOUS_HOST_PROXY's target and whether it answered, or null. A
-- nullable column added without a default rewrites nothing.
ALTER TABLE "workers" ADD COLUMN "host_proxy" jsonb;--> statement-breakpoint
ALTER TABLE "workers" ADD CONSTRAINT "workers_host_proxy_ck" CHECK ("workers"."host_proxy" is null or (jsonb_typeof("workers"."host_proxy") = 'object' and jsonb_typeof("workers"."host_proxy" -> 'target') is not distinct from 'string' and jsonb_typeof("workers"."host_proxy" -> 'reachable') is not distinct from 'boolean' and jsonb_typeof("workers"."host_proxy" -> 'checked_at') is not distinct from 'string'));--> statement-breakpoint
ALTER TABLE "experiments" ADD CONSTRAINT "experiments_pause_reason_ck" CHECK ("experiments"."pause_reason" is null or "experiments"."pause_reason" in ('user', 'spend_ceiling', 'provider_disconnected'));--> statement-breakpoint

-- run_events on a revoked attempt. 0001 refuses every event once recovery has
-- revoked an attempt's lease, so the old owner can add nothing more. But
-- recovery itself ends that attempt (plan 8.6 step 3) and must be able to say
-- so in its timeline: the `worker_lost` platform subtype exists for exactly
-- that, and `cancelled` when a cancel had been requested. Both are refused by
-- 0001, so a `worker_lost` event could never be written. This allows those two
-- platform subtypes, and nothing else, on an attempt that is revoked but not
-- yet finished. A finished attempt still takes no event at all, and artifacts
-- keep the 0001 rule unchanged (hermes_require_open_attempt).
CREATE FUNCTION hermes_run_events_require_open_attempt() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  attempt_finished_at timestamptz;
  attempt_revoked_at timestamptz;
BEGIN
  SELECT finished_at, lease_revoked_at INTO attempt_finished_at, attempt_revoked_at
    FROM attempts WHERE id = NEW.attempt_id FOR SHARE;
  IF attempt_finished_at IS NOT NULL
     OR (attempt_revoked_at IS NOT NULL
         AND NOT (NEW.type = 'platform' AND (NEW.payload ->> 'subtype') IN ('worker_lost', 'cancelled'))) THEN
    RAISE EXCEPTION 'attempt % has finished or lost its lease; no % may be added', NEW.attempt_id, TG_TABLE_NAME
      USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
DROP TRIGGER "run_events_require_open_attempt" ON "run_events";--> statement-breakpoint
CREATE TRIGGER run_events_require_open_attempt BEFORE INSERT ON run_events
  FOR EACH ROW EXECUTE FUNCTION hermes_run_events_require_open_attempt();
